const icons={world:'<path d="M4 15c0-6 4-9 8-9s8 3 8 9v4H4z"/><path d="M8 19v-5a4 4 0 0 1 8 0v5M12 6V3m0 2 4-2"/>',friends:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5"/>',book:'<path d="M12 6C8 3 5 4 2 5v15c4-2 7-1 10 0 3-1 6-2 10 0V5c-3-1-6-2-10 1Zm0 0v14"/>',leaf:'<path d="M12 21V10C8 4 3 4 2 4c0 8 5 11 10 8M12 15c1-8 7-10 10-10 0 7-5 11-10 10"/>',gear:'<path d="M19.391 8.939 L19.846 10.439 L21.808 10.049 L21.808 13.951 L19.846 13.561 L19.391 15.061 L19.391 15.061 L18.652 16.445 L20.315 17.556 L17.556 20.315 L16.445 18.652 L15.061 19.391 L15.061 19.391 L13.561 19.846 L13.951 21.808 L10.049 21.808 L10.439 19.846 L8.939 19.391 L8.939 19.391 L7.555 18.652 L6.444 20.315 L3.685 17.556 L5.348 16.445 L4.609 15.061 L4.609 15.061 L4.154 13.561 L2.192 13.951 L2.192 10.049 L4.154 10.439 L4.609 8.939 L4.609 8.939 L5.348 7.555 L3.685 6.444 L6.444 3.685 L7.555 5.348 L8.939 4.609 L8.939 4.609 L10.439 4.154 L10.049 2.192 L13.951 2.192 L13.561 4.154 L15.061 4.609 L15.061 4.609 L16.445 5.348 L17.556 3.685 L20.315 6.444 L18.652 7.555 L19.391 8.939 Z"/><circle cx="12" cy="12" r="3.2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>'};
const icon=k=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[k]+'</svg>';
const native=window.RidleyNative,KEY='forest-of-space-v1';let inspector=null,inspectionCamera=null,stageLab=null;let state,tab='world',selected=null,patchSelected=null,dex='species',editor=false,ready=false,storageFailed=false,foreground=!document.hidden,last=performance.now(),acc=0,lastSave=0,toastTimer,returnPage='world',pendingImport=null,facilityDraft=null;
function notice(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5500);}
function rawRead(){return native?native.read():localStorage.getItem(KEY)||'';}
function write(s){try{const next=F.clone(s);next.savedAt=Math.max(next.savedAt,Date.now());const text=JSON.stringify(next);if(native){if(!native.save(text))return false;}else localStorage.setItem(KEY,text);s.savedAt=next.savedAt;return true;}catch{return false;}}
function archive(s){const text=typeof s==='string'?s:JSON.stringify(s);try{if(native)return native.archive(text);const previous=JSON.parse(localStorage.getItem(KEY+'-history')||'[]');previous.unshift({at:Date.now(),text});localStorage.setItem(KEY+'-history',JSON.stringify(previous.slice(0,10)));return true;}catch{return false;}}
function archiveRead(){return native?native.readArchive():(JSON.parse(localStorage.getItem(KEY+'-history')||'[]')[0]?.text||'');}
function commit(fn,after){if(inspector){notice('검수 화면에서는 실제 기록을 바꾸지 않아요.');return false;}try{state=F.transaction(state,fn,write);storageFailed=false;after?.();update();return true;}catch(e){notice(e.message);return false;}}
const portrait=id=>id==='bonbon'?'assets/forest/species/ellisii-portrait.png':id==='superbum'?'assets/forest/species/superbum-portrait.png':id==='neolbi'?'assets/forest/neolbi/portrait.png':['bonbon','bosong','jureong','duri'].includes(id)?'assets/forest/species/'+id+'-portrait.png':'assets/forest/ridley.png';
const speciesName=p=>F.SPECIES.find(x=>x[0]===p.species)?.[1]||'친구';
// small neighbours on this friend's leaves (SRS ECO-09: say what they do and why, no raw density)
function leafNote(p){const on=F.Creatures?.onLeaf?.(state,p.id);if(!on)return '';const roots=F.Creatures.rootsNear?.(state,p);const m=on.mite,k=on.keeper;
 if(on.mealy){if(on.lady)return on.lady.stage==='larva'?' · 점박이 유충이 솜깍지를 먹는 중':' · 점박이가 솜깍지 알주머니를 살피는 중';if(on.ant)return ' · 짐꾼개미가 솜깍지의 감로 곁에 머물러요';return on.mealy.density>=30?' · 잎 사이 솜깍지가 늘어 영양이 덜 가요. 잎을 정돈하거나 쉼터에서 쉬면 줄어요':' · 잎 사이에 솜깍지가 붙어 있어요';}
 if(on.lady)return ' · 점박이가 남은 솜깍지를 살피는 중';
 if(!m&&!k&&roots)return (()=>{const S=F.Creatures.inSoil(state,roots.z.id),who=[S.soilmite&&'흙지기',S.rove&&'쏙쏙이'].filter(Boolean).join('·');return who?' · '+who+'가 젖은 낙엽 속 뿌리날파리 유충을 줄이는 중':' · 젖은 낙엽 곁이라 뿌리날파리 유충이 뿌리를 귀찮게 해요';})();
 if(k&&m)return ' · 잎지기가 잎응애를 찾아 먹는 중';if(k)return ' · 잎지기가 남은 잎응애를 살피는 중';if(!m)return '';const l=F.Creatures.leaf(state,p);return m.density>=30?' · 잎응애가 늘어 잎이 지쳐요. 그늘·물가에서 쉬면 줄어요':l.H>55||l.wet||l.inside?' · 잎이 촉촉해져 잎응애가 줄고 있어요':' · 마른 잎에 잎응애가 머물러요';}
// SRS v2.28 species traits: strong and weak points from the motif fern (detail page and the guide)
function traitText(id){const t=globalThis.ForestTraits?.text(id);if(!t||!t.good.length)return '';return '\n\n강한 점\n'+t.good.map(x=>'· '+x).join('\n')+'\n\n약한 점\n'+t.bad.map(x=>'· '+x).join('\n');}
function traitHtml(id){const t=globalThis.ForestTraits?.text(id);if(!t||!t.good.length)return '';const li=a=>a.map(x=>'<li>'+escape(x)+'</li>').join('');return '<div class="panel traits"><h3>타고난 특성</h3><div class="trait-cols"><div><small>강한 점</small><ul>'+li(t.good)+'</ul></div><div><small>약한 점</small><ul>'+li(t.bad)+'</ul></div></div></div>';}
function actionReason(p){if(!p.active)return '정원 밖에서 쉬고 있어요 · 친구들 화면에서 정원에 들일 수 있어요';if(p.mounted||(p.shelter?.phase&&p.shelter.phase!=='outside')||p.action==='rest'&&p.target==='shelter'&&!p.protectedBy)return F.Shelter.label(state,p);if(F.Objects.reason(state,p))return F.Objects.reason(state,p);if(p.protectedBy)return '엘레판의 잎 아래서 비와 바람을 피하고 있어요';if(p.wetRecovery)return '뿌리가 오래 젖어 마른 자리로 가요';if(p.leafRecovery||p.damage>=10)return '잎이 지쳐 안전한 곳에서 쉬어요';if(p.motion?.kind==='umbrella')return '큰 잎으로 친구의 빗방울을 덜어줘요';if(p.species==='bonbon'&&F.Social.ellisiiHabitat(state,p))return '잎틈에서 작은 이웃이 쉬기 좋은 자리를 살펴요';if(p.motion?.kind==='share')return '모아 둔 물을 친구에게 나눠요';if(p.species==='superbum'&&p.restSelf)return '둥지잎을 접고 제자리에서 쉬어요';if(p.species==='superbum'&&p.harvestTick>0)return '둥지잎에 빗물을 모으고 있어요';if(p.motion?.kind==='receive')return '친구가 건넨 물을 마셔요';if(p.motion?.kind==='shade')return '큰 잎으로 그늘을 만들어요';if(p.mounted)return '목부작 자리에서 쉬고 있어요';if(p.action==='drink')return p.motion?.water>0?'물가에서 천천히 물을 마시고 있어요':'목이 말라 샘터로 가고 있어요';if(p.motion?.kind==='run')return '바람을 피해 쉼터로 달려가요';if(p.action==='rest')return p.protectedBy?'잎 그늘 아래서 쉬고 있어요':F.Shelter.label(state,p);if(p.action==='groom')return '자기 잎을 살며시 정돈하고 있어요';return '정원의 작은 변화를 살피고 있어요';}
function stats(p){return '<div class="stats">'+[['수분','B'],['체력','energy'],['기분','mood'],['영양','nutrition']].map(([label,k])=>'<div class="stat"><span>'+label+'</span><progress max="100" value="'+p[k]+'" aria-label="'+label+'"></progress><b>'+Math.round(p[k])+'</b></div>').join('')+'</div>';}
const scene=new ForestScene($('garden'),()=>inspector?.state||state),audio=new ForestAudio.Player();
scene.onCamera=()=>{$('overview').textContent=scene.camera.overview?'이전 시점':'전체 보기';};
const carry=new ForestCarry($('world'),scene,()=>state,commit,notice);
$('cancel-carry').onclick=()=>carry.cancel();
scene.onCarry=active=>{if(active){closeCard();if(carry.held){audio.cancelShots(carry.held);audio.marker('pickup:'+performance.now(),'groom',carry.held);}}scene.cameraChanged();targets();};
scene.onMarker=(id,cue,emitter)=>{if(!inspector)audio.marker(id,cue,emitter);};
const landed=scene.landed.bind(scene);scene.landed=id=>{landed(id);audio.marker('land:'+performance.now(),'putdown',id);};
document.addEventListener('pointerdown',()=>audio.unlock(),{passive:true});
document.addEventListener('keydown',()=>audio.unlock(),{passive:true});
document.addEventListener('click',e=>{if(!inspector&&foreground&&e.target.closest('button'))audio.marker('ui:'+performance.now(),'click','ui');},{passive:true});
scene.onSelect=(kind,id)=>{if(kind==='pet'){selected=id;patchSelected=null;scene.selected=id;showCard();}else if(kind==='patch'||kind==='spring'||kind==='facility'){selected=null;scene.selected=null;patchSelected=id;showCard();}else closeCard();};
scene.onMove=(id)=>{scene.selectedPatch=id;renderEditor();};
function targets(){const root=$('targets');root.replaceChildren();for(const p of state.individuals.filter(p=>p.active)){const b=document.createElement('button');b.className='pet-target';b.dataset.pet=p.id;b.setAttribute('aria-label',p.name+' · '+speciesName(p)+' 선택');b.addEventListener('click',()=>scene.onSelect('pet',p.id));const label=document.createElement('span');label.className='pet-label';label.hidden=!state.settings.showName&&!state.settings.showLevel;label.textContent=[state.settings.showName?p.name:'',state.settings.showLevel?'Lv.'+F.level(p):''].filter(Boolean).join(' · ');b.append(label);root.append(b);}}
function closeCard(){delete $('select-card').dataset.key;delete $('select-card').dataset.objectId;delete $('select-card').dataset.objectHtml;$('select-card').classList.remove('object-card');selected=null;patchSelected=null;scene.selected=null;$('select-card').hidden=true;}
function updateObjectCard(card,id){const html=ForestObjectCards.render(state,id,icon('close'));if(!html){closeCard();return;}
 const same=card.dataset.objectId===id;if(same&&card.dataset.objectHtml===html)return;
 const scroll=same?card.scrollTop:0,open=same&&card.querySelector('[data-object-details]')?.open,focused=card.contains(document.activeElement)?document.activeElement?.dataset.action:null,summaryFocused=same&&document.activeElement===card.querySelector('summary');
 card.innerHTML=html;card.dataset.objectId=id;card.dataset.objectHtml=html;card.classList.add('object-card');
 const details=card.querySelector('[data-object-details]');if(details)details.open=!!open;card.scrollTop=scroll;
 if(focused)card.querySelector('[data-action="'+focused+'"]')?.focus({preventScroll:true});else if(summaryFocused)card.querySelector('summary')?.focus({preventScroll:true});
}
function previewObjectUpgrade(id){try{const next=F.Objects.planUpgrade(state,id),u=F.Objects.upgradeStatus(state,id);scene.objectExpansionPreview={id,scale:F.Objects.scale(next,id)};const cancel=()=>{scene.objectExpansionPreview=null;closeDialog();};dialog('자리를 넓힐까요?','보유량 '+u.capacity+' → '+u.nextCapacity+'. 지금 남아 있는 양은 그대로이고 비용은 없어요.',[{label:'취소',fn:cancel},{label:'넓히기',fn:()=>commit(s=>{F.Objects.upgrade(s,id);F.event(s,'object-upgrade','자리를 넓혔어요.',{object:id});},()=>{cancel();showCard();})}]);}catch(e){notice(e.message);}}
function showCard(){if(editor)return;const card=$('select-card');if(!selected&&!patchSelected){card.hidden=true;return;}card.hidden=false;
 if(selected){card.classList.remove('object-card');delete card.dataset.objectId;delete card.dataset.objectHtml;const p=state.individuals.find(x=>x.id===selected);if(!p){closeCard();return;}const key=p.id+'|'+p.name+'|'+state.settings.showState;if(card.dataset.key===key){card.querySelector('.badge').textContent='Lv.'+F.level(p);card.querySelector('.select-head p').textContent=actionReason(p)+leafNote(p);card.querySelectorAll('progress').forEach((el,i)=>{const value=p[['B','energy','mood','nutrition'][i]];el.value=value;el.nextElementSibling.textContent=Math.round(value);});return;}card.dataset.key=key;card.innerHTML='<div class="select-head"><img class="portrait" src="'+portrait(p.species)+'" alt=""><div><h2>'+escape(p.name)+' <span class="badge">Lv.'+F.level(p)+'</span></h2><p>'+actionReason(p)+escape(leafNote(p))+'</p></div><button class="icon close" data-action="close-card" aria-label="선택 닫기">'+icon('close')+'</button></div>'+(state.settings.showState?stats(p):'<p class="sub">상태 수치는 설정에서 다시 켤 수 있어요.</p>')+'<div class="button-pair"><button class="secondary" data-action="move-pet" data-id="'+escape(p.id)+'">옮기기</button><button class="primary" data-action="detail" data-id="'+escape(p.id)+'">자세히 보기</button></div>';
 }else {delete card.dataset.key;if(patchSelected==='shelter')patchSelected='shelter-0';updateObjectCard(card,patchSelected);}
}

function switchTab(next){if(tab==='visit'&&next!=='visit'&&state.recruitment.visitor?.open)commit(s=>F.Recruitment.close(s));facilityDraft=null;scene.facilityPreview=null;if(inspector)endInspector();scene.camera.setBottomOcclusion(0);$('world').classList.remove('editing-layout');carry.cancel();audio.cancelShots();scene.silentTick=state.worldTick;if(editor){editor=false;scene.editing=false;scene.preview={};$('editor').hidden=true;$('targets').hidden=false;}tab=next;closeCard();$('world').hidden=next!=='world';$('page').hidden=next==='world';scene.paused=next!=='world'||!foreground;$('nav').querySelectorAll('button').forEach(b=>{const active=b.dataset.tab===next;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(next==='world'){scene.measure();targets();}else renderPage();}
function renderPage(){const page=$('page'),p=state.individuals[0];
 if(tab==='visit'){renderVisit();return;}
 if(tab==='friends'){page.innerHTML='<h2>함께 지내는 친구</h2><p class="sub">각자의 속도로, 같은 정원에서.</p><div class="section-title"><span>정원에서 생활 중</span><span class="badge">'+state.individuals.filter(x=>x.active).length+' / 5</span></div>'+state.individuals.map(x=>'<button class="friend-card" data-action="detail" data-id="'+escape(x.id)+'"><img src="'+portrait(x.species)+'" alt=""><div><h3>'+escape(x.name)+'</h3><p>'+speciesName(x)+' · Lv.'+F.level(x)+'</p><p class="sub">'+actionReason(x)+'</p></div></button>').join('')+recruitmentPanel();}
 else if(tab==='detail'){const x=state.individuals.find(x=>x.id===selected)||p;page.innerHTML='<button class="text-button" data-action="detail-back">‹ 돌아가기</button><div class="detail-hero"><img src="'+portrait(x.species)+'" alt="'+speciesName(x)+'"><h2>'+escape(x.name)+' <span class="badge">Lv.'+F.level(x)+'</span></h2><p class="sub">'+speciesName(x)+' · '+F.SPECIES.find(z=>z[0]===x.species)[3]+'</p></div><div class="panel"><p>'+actionReason(x)+'</p>'+stats(x)+'<div class="data-grid"><div><small>뿌리의 젖음</small><strong>'+Math.round(x.Q*5)+' / 100</strong></div><div><small>성장 경험</small><strong>'+x.xp+' XP</strong></div><div><small>잎 손상</small><strong>'+Math.round(x.damage)+' / 100</strong></div><div><small>과습 부담</small><strong>'+Math.round(x.burden)+' / 100</strong></div></div></div>'+traitHtml(x.species)+'<p class="sub">건강한 생활 6분마다 1 XP가 쌓여요. 조경과 목부작에서는 성장하지 않아요.</p><button class="secondary" data-action="rename">별명 바꾸기</button><div class="row"><label>목부작으로 쉬기<small>외부 활동과 성장을 쉬고 회복해요.</small></label>'+toggle('mounted',x.mounted)+'</div><button class="secondary" data-action="roster" data-id="'+escape(x.id)+'">'+(x.active?'대기로 옮기기':'정원에 들이기')+'</button><button class="primary" data-action="find-pet">정원에서 보기</button>';}
 else if(tab==='dex'){page.innerHTML='<h2>숲의 도감</h2><p class="sub">직접 마주친 순간들을 모아요.</p><div class="chips">'+[['species','식물 친구'],['moments','생활 기록'],['neighbors','작은 이웃'],['environment','환경 발견']].map(([key,label])=>'<button class="chip '+(key===dex?'active':'')+'" data-dex="'+key+'">'+label+'</button>').join('')+'</div>';
  if(dex==='species')page.innerHTML+='<div class="dex-grid">'+F.SPECIES.filter(([id])=>!F.Recruitment.retired.includes(id)||state.individuals.some(p=>p.species===id)).map(([id,name,latin,desc])=>{const owned=state.individuals.some(p=>p.species===id);return '<button class="dex-card '+(owned?'':'locked')+'" data-action="species" data-species="'+id+'">'+(owned?'<img src="'+portrait(id)+'" alt="'+name+'">':'<div class="unknown">잎</div>')+'<div>'+name+'</div><small>'+(owned?'우리 정원의 친구':'다음 만남을 기다려요')+'</small></button>';}).join('')+'</div>';
  else if(dex==='neighbors'){const seen=state.objects?.creatures?.seen||{};
   // SRS NAM-03: say the current relationship, never 'good/bad bug'; ECO-09: name, class, role, why it is here, food, when it leaves
   const N=[['돌돌이','Armadillidium vulgare · 육상 등각류(갑각류)','비 갠 뒤 촉촉한 이끼 곁, 물이 고이지 않은 바위틈에 쉬러 와요. 머무는 동안 바위틈 근처 낙엽 분해를 조금(×1.1) 도와요. 친구가 가까이 오면 공처럼 말려요.',!!state.discoveries.neighbor],
    ['짐꾼개미','개미 · 곤충','리들리마다 곁 흙더미에 군락을 이뤄(숲에 3군락까지) 낮에 둥지 둘레의 흩어진 낙엽을 낙엽더미로 날라요. 밤이나 비·눈·강풍에는 둥지에서 쉬고, 솜깍지의 감로가 많으면 그 곁을 지켜요.',!!seen.ant],
    ['톡토기','Collembola · 톡토기류','촉촉한 낙엽더미에 머물며 그 더미의 분해를 1.25배 도와요. 엘리시가 가까이 있으면 더 잘 찾아와요.',!!seen.springtail],
    ['잎응애','Tetranychus 계열 · 진드기류','덥고 마른 잎(뜨거운 햇살 바위, 목마름)에 자리를 잡고 늘어나면 잎이 지쳐요. 잎이 촉촉해지거나 친구가 잎을 정돈하면 줄어요.',!!seen.mite],
    ['잎지기','Phytoseiulus persimilis · 진드기류','잎응애가 실제로 있고 잎이 적당히 촉촉할 때 찾아와 잎응애를 먹어요. 먹이가 없으면 떠나요.',!!seen.keeper],
    ['뿌리날파리','Bradysia 계열 · 곤충','젖어서 썩어 가는 낙엽에 알을 낳아요. 유충이 그 자리 친구의 뿌리를 귀찮게 해요. 낙엽이 마르면 줄어요.',!!seen.gnat],
    ['흙지기','Stratiolaelaps scimitus · 진드기류','물이 빠진 촉촉한 흙에서 뿌리날파리 유충과 알을 먹어요. 잎응애는 맡지 않아요.',!!seen.soilmite],
    ['쏙쏙이','Dalotia coriaria · 반날개(곤충)','바위틈이나 햇살 바위를 은신처로 삼아 젖은 낙엽의 뿌리날파리 유충을 찾아요. 가끔 바위 뒤로 쏙 숨어요.',!!seen.rove],
    ['솜깍지','알주머니형 깍지벌레 · 곤충','따뜻한 잎 사이에 붙어 영양을 조금 빼앗고, 많아지면 알주머니와 달콤한 감로를 남겨요.',!!seen.mealy],
    ['점박이','Cryptolaemus montrouzieri · 곤충','솜깍지 알주머니가 있을 때 찾아와 살펴본 뒤 유충이 솜깍지를 먹어요. 개미가 감로를 지키면 느려져요.',!!seen.lady]];
   // 0.6.32: each entry shows its picture once met (a dark silhouette until then) and the page counts the met ones
    const pics={'돌돌이':'pillbug','짐꾼개미':'ant-body','톡토기':'springtail-rest','잎응애':'spidermite','잎지기':'predatory-mite','뿌리날파리':'root-gnat','흙지기':'soil-mite','쏙쏙이':'rove-beetle','솜깍지':'mealybug','점박이':'ladybird'};
    page.innerHTML+='<p class="sub">만난 이웃 '+N.filter(x=>x[3]).length+' / '+N.length+' · 숲에 한 번이라도 찾아오면 채워져요.</p>'+N.map(([n,sci,role,met])=>'<div class="panel neighbour-entry'+(met?'':' unmet')+'"><img src="assets/forest/creatures/'+pics[n]+'.png" alt="'+(met?n:'아직 못 만난 이웃')+'"><div><h3>'+(met?n:n+' <span class="badge">아직 못 만났어요</span>')+'</h3><p>'+role+'</p><p class="sub">'+sci+' · 도감 그림은 확대 표현이에요.</p></div></div>').join('');}
  else {const rows=Object.entries(state.discoveries).filter(([key])=>dex==='environment'?key.startsWith('EC'):!key.startsWith('EC'));page.innerHTML+=rows.length?rows.map(([id,d])=>'<div class="panel"><p>'+escape(d.text)+'</p><small class="sub">정원에서 직접 관찰한 기록</small></div>').join(''):'<div class="empty">아직 적힌 순간이 없어요.<br>정원에서 생활과 변화를 지켜봐 주세요.</div>';}
 }
 else if(tab==='settings'){page.innerHTML='<h2>정원의 설정</h2><p class="sub">편안한 방식으로 함께해요.</p><h3>표시와 움직임</h3><div class="settings-group">'+[['showName','이름 표시'],['showLevel','레벨 표시'],['showState','선택 카드 상태 표시'],['showSpeech','생활 안내 표시'],['reducedMotion','움직임 줄이기']].map(([key,label])=>'<div class="row"><label>'+label+'</label>'+toggle(key,state.settings[key])+'</div>').join('')+'<div class="row"><label>화면 밝기<small>연출만 변경하고 게임 시계는 유지해요.</small></label><select id="theme" aria-label="화면 밝기"><option value="auto">시간에 맞게</option><option value="day">밝게</option><option value="night">어둡게</option></select></div></div><h3>소리</h3><div class="settings-group">'+[['master','전체'],['music','배경 음악'],['environment','정원의 소리'],['effects','행동 효과음']].map(([key,label])=>'<div class="row"><label for="volume-'+key+'">'+label+'</label><input id="volume-'+key+'" data-volume="'+key+'" type="range" min="0" max="100" value="'+Math.round(state.settings.audio[key]*100)+'" aria-label="'+label+' 음량"><output>'+Math.round(state.settings.audio[key]*100)+'</output></div>').join('')+'</div><h3>쉼터</h3><button class="secondary" data-action="facility-home">쉼터 공간 관리</button><h3>개발 검수</h3><button class="secondary" data-action="inspect">관리자 모드 열기</button><p class="sub">날씨와 모션을 선택해 구현 상태를 확인해요. 실제 정원 기록은 유지돼요.</p><h3>기록 보관</h3><p class="sub">이 기기에 저장해요. 휴대폰을 바꾸기 전에는 백업을 내보내 주세요.</p><div class="button-pair"><button class="secondary" data-action="export">백업 내보내기</button><button class="secondary" data-action="import">백업 가져오기</button></div><button class="text-button" data-action="restore-last">최근 안전 백업 복원</button>'+(state.legacy?'<div class="panel"><p>이전 모바일 기록을 안전하게 보관하고 있어요.</p><button class="text-button" data-action="export-legacy">이전 기록 내보내기</button></div>':'')+'<h3>여백의 숲</h3><div class="panel"><p>개발 빌드 '+F.VERSION+' · 2단계 기능 검수</p><p class="sub">현재: 리들리 자율 생활·들기와 버둥거림, 지도 확대·탐색, 꾸미기, 샘터 흐름·그늘 가림, 성장·저장·백업.<br>별도 검수: 엘리시 잎틈 정원·엘레판 그늘·복수 편성. 엘레판 최종 외형·쉼터 실제 입실·공간 수용과 확장 적용.<br>현재: 조건 방문·만남·정착, 안전한 쉼터 순번, 전체 날씨와 공통 조명.<br>후속: 전체 협동·작은 이웃의 먹이 행동.</p><button class="text-button" data-action="home">시작 화면 보기</button></div>';page.querySelectorAll('[data-volume]').forEach(el=>{el.addEventListener('input',()=>{el.nextElementSibling.value=el.value;audio.volume({...state.settings.audio,[el.dataset.volume]:Number(el.value)/100});});el.addEventListener('change',()=>{if(!commit(s=>s.settings.audio[el.dataset.volume]=Number(el.value)/100)){el.value=state.settings.audio[el.dataset.volume]*100;el.nextElementSibling.value=el.value;audio.volume(state.settings.audio);}});});const climateBox=document.createElement('div');climateBox.className='panel';climateBox.innerHTML='<h3>숲의 기후</h3><p class="sub">30초 뒤 천천히 바뀌어요. 폭풍이 끝나면 전환해요.</p><select id="climate-choice" aria-label="기후">'+Object.entries(F.Environment.CLIMATES).map(([id,c])=>'<option value="'+id+'">'+c.name+'</option>').join('')+'</select>';page.insertBefore(climateBox,page.children[2]);$('climate-choice').value=state.environment.climate;$('climate-choice').onchange=e=>commit(s=>F.Environment.changeClimate(s,e.target.value));$('theme').value=state.settings.theme;$('theme').addEventListener('change',e=>commit(s=>s.settings.theme=e.target.value));}
}
function recruitmentPanel(){const r=state.recruitment,v=r.visitor;return '<div class="panel"><h3>숲에 찾아오는 친구</h3>'+(v?'<p>'+escape(F.Recruitment.josa(v.pet.name,'이','가'))+' 입구에서 기다리고 있어요. 만나기 전까지는 다른 친구의 준비 시간이 멈춰요.</p><button class="primary" data-action="visit">만나러 가기</button>':'<p class="sub">환경을 마련하면 친구가 찾아와요. 한 번에 한 친구를 만나요.</p>')+F.SPECIES.filter(([id])=>!state.individuals.some(p=>p.species===id)&&!F.Recruitment.retired.includes(id)).map(([id,name])=>{const c=F.Recruitment.conditions(state,id,F.Space,F.Social),p=r.progress[id];return '<div class="recruit-row"><strong>'+name+'</strong><p>'+c.reason+'</p>'+(c.checks?.length?'<ul class="recruit-checks">'+c.checks.map(k=>'<li class="'+(k.ok?'ok':'no')+'">'+(k.ok?'✓ ':'· ')+escape(k.label)+' <span>(필요: '+escape(k.need)+')</span></li>').join('')+'</ul>':'')+'<small>조건이 180초 이어지면 35% 확률로 찾아와요(세 번 놓치면 다음엔 꼭). 준비된 시간 '+p.valid+' / 180초 · 기다린 차례 '+p.failures+' / 3</small><button class="text-button" data-action="recruit-target" data-species="'+id+'">'+(r.target===id?'먼저 기다리는 중':'먼저 기다리기')+'</button></div>';}).join('')+'</div><div class="panel"><h3>함께 지낼 예정 명단</h3><p class="sub">성체가 되었을 때 필요한 공간까지 준비해요.</p>'+state.individuals.map(p=>'<label class="row"><span>'+escape(p.name)+'</span><input type="checkbox" data-planned value="'+escape(p.id)+'" '+(state.shelters.plannedRoster.includes(p.id)?'checked':'')+'></label>').join('')+'<button data-action="plan-roster" class="secondary">명단 저장</button></div>';}
function renderVisit(){const v=state.recruitment.visitor;if(!v){switchTab('friends');return;}$('page').innerHTML='<button class="text-button" data-action="visit-close">‹ 정원으로 돌아가기</button><h2>'+escape(F.Recruitment.josa(v.pet.name,'과','와'))+' 첫 만남</h2><p class="sub">만나는 동안 정원의 생활은 잠시 쉬어요.</p><canvas id="visit-canvas" width="720" height="580" style="width:100%;height:auto;border-radius:24px" aria-label="친구와 만나는 작은 자리"></canvas><div class="panel"><p id="visit-status"></p><p class="sub">'+F.Recruitment.goals[v.species]+'</p><ul id="visit-steps" class="recruit-checks"></ul><p id="visit-leave" class="sub"></p><div class="button-pair">'+(F.Recruitment.steps(state).buttons.greet?'<button class="secondary" data-action="visit-greet">반갑게 인사하기</button>':'')+(F.Recruitment.steps(state).buttons.guide?'<button class="secondary" data-action="visit-guide">물 있는 곳 알려주기</button>':'')+'</div><button id="visit-settle" class="primary" data-action="visit-settle">함께 살기</button></div>';updateVisit();drawVisit(performance.now()/1000);}
function updateVisit(){const v=state.recruitment.visitor;if(!v||!$('visit-status'))return;const p=state.recruitment.progress[v.species];$('visit-status').textContent=v.ready?'함께 살 준비가 됐어요.':v.seconds<30?'새로운 자리에 천천히 익숙해져요.':({walk:'주변을 살펴보며 걸어요.',water:'잎에 물을 모으고 물을 살펴봐요.',sun:'햇빛이 드는 자리를 살펴봐요.',shade:'시원한 그늘을 확인해요.',pick:'낙엽을 조심히 주워요.',carry:'낙엽을 마른 자리로 옮겨요.',rest:'편안하게 쉬고 있어요.',spring:'샘터의 물을 살펴봐요.',sky:'둥지잎을 펼치고 하늘을 올려다봐요.'})[v.phase]||'서로 익숙해지고 있어요.';$('visit-settle').disabled=!v.ready||state.individuals.length>=50;const st=F.Recruitment.steps(state);if(st&&$('visit-steps')){$('visit-steps').innerHTML=st.list.map(k=>'<li class="'+(k.done?'ok':'no')+'">'+(k.done?'✓ ':'· ')+escape(k.label)+(k.value?' <span>'+escape(k.value)+'</span>':'')+'</li>').join('');$('visit-leave').textContent=st.ready?'':'만남 화면을 열어 둔 동안만 시간이 흘러요. 준비가 안 된 채 '+Math.ceil(st.leaveIn/60)+'분이 더 지나면 친구가 잠시 돌아가요.';}}
function drawVisit(t){const canvas=$('visit-canvas'),v=state.recruitment.visitor;if(!canvas||!v)return;const c=canvas.getContext('2d'),A=scene.assets;c.clearRect(0,0,720,580);
 // 0.6.30 card scene: the world's own painted ground with its fern borders, a soft worn path into a lit clearing,
 // the guest's real props on the ground and the characters larger, back to front with contact shadows.
 const g=A.garden;if(g){const sh=g.width*580/720;c.drawImage(g,0,g.height-sh,g.width,sh,0,0,720,580);}else{c.fillStyle='#f7f0e2';c.fillRect(0,0,720,580);}
 c.save();c.scale(2,2);
 const soft=(f,b)=>{c.save();c.filter='blur('+b+'px)';f();c.restore();};
 // lit clearing and a gentle darkening toward the corners
 const glow=c.createRadialGradient(180,175,10,180,175,200);glow.addColorStop(0,'rgba(255,248,226,.62)');glow.addColorStop(.6,'rgba(255,248,226,.18)');glow.addColorStop(1,'rgba(255,248,226,0)');c.fillStyle=glow;c.fillRect(0,0,360,290);
 const edge=c.createRadialGradient(180,160,120,180,160,260);edge.addColorStop(0,'rgba(110,88,58,0)');edge.addColorStop(1,'rgba(110,88,58,.16)');c.fillStyle=edge;c.fillRect(0,0,360,290);
 // the worn path from the entrance (bottom) into the clearing
 soft(()=>{c.fillStyle='rgba(150,118,80,.10)';for(const [x,y,rx,ry] of [[184,286,46,14],[178,262,40,12],[172,240,44,12],[178,218,56,14],[180,200,74,18]]){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill();}},5);
 soft(()=>{c.fillStyle='rgba(255,252,240,.35)';c.beginPath();c.ellipse(180,200,64,13,0,0,Math.PI*2);c.fill();},6);
 // soft morning rays from the upper left, and a few fallen leaves on the ground (fixed places, no randomness)
 soft(()=>{c.globalCompositeOperation='lighter';for(const [x,w,a] of [[40,34,.045],[110,22,.03],[170,40,.04]]){c.fillStyle='rgba(255,236,190,'+a+')';c.beginPath();c.moveTo(x-20,-10);c.lineTo(x-20+w,-10);c.lineTo(x+w+150,300);c.lineTo(x+110,300);c.closePath();c.fill();}},8);
 for(const [x,y,r,col] of [[118,236,.6,'rgba(196,150,86,.55)'],[262,268,-.4,'rgba(176,138,82,.5)'],[214,178,1.2,'rgba(206,170,96,.45)'],[64,250,2.2,'rgba(170,150,90,.45)'],[300,206,.2,'rgba(190,140,80,.4)']]){c.save();c.translate(x,y);c.rotate(r);c.fillStyle=col;c.beginPath();c.ellipse(0,0,5.5,2.4,0,0,Math.PI*2);c.fill();c.strokeStyle='rgba(120,90,50,.35)';c.lineWidth=.5;c.beginPath();c.moveTo(-5,0);c.lineTo(5,0);c.stroke();c.restore();}
 const terr=(ix,x,y,size)=>{const im=A.terrain;if(!im)return;const sw=im.width/3,sh=im.height/2;soft(()=>{c.fillStyle='rgba(90,72,48,.16)';c.beginPath();c.ellipse(x,y+size*.02,size*.38,size*.075,0,0,Math.PI*2);c.fill();},2);c.drawImage(im,(ix%3)*sw,Math.floor(ix/3)*sh,sw,sh,x-size/2,y-size*.75,size,size);};
 const sp=v.species;
 if(sp==='bonbon'){terr(3,166,128,110);terr(1,92,162,104);}
 if(sp==='bosong')scene.springAt(c,{...state,spring:{...state.spring,water:v.water*3,inflow:4/60},individuals:[],weather:{kind:'sun'}},80,184,.82,t);
 if(sp==='neolbi'){c.drawImage(A.shadePlant,52,48,134,134);c.drawImage(A.shadeGround,52,48,134,134);const sun=c.createRadialGradient(262,162,4,262,162,52);sun.addColorStop(0,'rgba(255,238,184,.42)');sun.addColorStop(1,'rgba(255,238,184,0)');c.fillStyle=sun;c.beginPath();c.ellipse(262,162,54,22,0,0,Math.PI*2);c.fill();}
 if(sp==='jureong'){terr(4,276,232,96);terr(0,172,150,92);}
 if(sp==='superbum')scene.springAt(c,{...state,spring:{...state.spring,water:60,inflow:0},individuals:[],weather:{kind:'sun'}},56,200,.72,t);
 // characters drawn back to front, each with a soft contact shadow
 const R=100,draw=(species,x,y,kind,phase)=>{soft(()=>{c.fillStyle='rgba(74,60,40,.22)';c.beginPath();c.ellipse(x,y+1,R*.27,R*.055,0,0,Math.PI*2);c.fill();},1.5);c.save();c.translate(x,y);c.scale(R/1254,R/1254);c.translate(-627,-1065.9);ForestRig.draw(c,A,{species,kind,phase,expression:kind==='rest'?'sleepy':'neutral',reduced:state.settings.reducedMotion});c.restore();};
 const kind=v.phase==='sky'?'collect':v.phase==='water'?'drink':v.phase==='pick'||v.phase==='carry'?'litter':v.phase==='walk'?'walk':v.phase==='rest'?'rest':'idle',actors=[{species:v.species,x:v.x*360,y:v.y*290,kind}];if(v.companion)actors.push({species:v.companion,x:sp==='jureong'?128:250,y:240,kind:'rest'});
 actors.sort((a,b)=>a.y-b.y).forEach(a=>draw(a.species,a.x,a.y,a.kind,t));c.restore();}
function toggle(k,value){return '<button class="switch" role="switch" aria-label="'+({mounted:'목부작으로 쉬기',showName:'이름 표시',showLevel:'레벨 표시',showState:'선택 카드 상태 표시',showSpeech:'생활 안내 표시',reducedMotion:'움직임 줄이기'}[k])+'" aria-checked="'+value+'" data-toggle="'+k+'"></button>';}
function syncEditorViewport(){const canvas=$('garden').getBoundingClientRect(),panel=inspector?$('inspect-panel'):editor?$('editor'):null;scene.camera.setBottomOcclusion(panel&&!panel.hidden?Math.max(0,canvas.bottom-panel.getBoundingClientRect().top):0);scene.cameraChanged();}
function focusInspection(){syncEditorViewport();const p=inspector.state.individuals[0];scene.camera.cx=p.x;scene.camera.cy=p.y;scene.camera.clamp();scene.cameraChanged();}
const editorViewportObserver=new ResizeObserver(syncEditorViewport);editorViewportObserver.observe($('editor'));editorViewportObserver.observe($('garden'));editorViewportObserver.observe($('inspect-panel'));
function renderEditor(){if(facilityDraft)return renderFacilityEditor();const p=scene.selectedPatch==='spring'?{...state.spring,id:'spring',name:'샘터'}:state.patches.find(x=>x.id===scene.selectedPatch);let message={spring:'돌과 물, 물 마시는 위치를 함께 옮겨요.',moss:'놀며 천천히 쉬는 자리예요. 물은 조금만 보관해요.',rock:'햇빛과 물 빠짐을 관찰할 수 있어요.',shade:'주변의 빛을 줄이는 실제 그늘이에요.',crevice:'이끼와 그늘을 가까이 두면 쉬어 갈 곳이 돼요.',litter:'낙엽을 옮겨도 원래 양은 유지돼요.'}[p.id],bad=false;try{F.validateLayout(state,scene.preview);}catch(e){message=e.message;bad=true;}
 $('editor').innerHTML='<button class="editor-fold" data-action="fold-editor" aria-expanded="'+!$('editor').classList.contains('folded')+'">'+($('editor').classList.contains('folded')?'배치 도구 펼치기':'배치 도구 접기')+'</button><div class="chips">'+[...state.patches,{...state.spring,id:'spring',name:'샘터'}].filter(p=>p.id!=='shelter').map(x=>'<button class="chip '+(p.id===x.id?'active':'')+'" data-patch="'+x.id+'">'+x.name+'</button>').join('')+'</div><p class="'+(bad?'bad':'')+'">'+(bad?'× ':'')+message+'</p><div class="position-pad" aria-label="선택한 자리 이동">'+[['left','←'],['up','↑'],['down','↓'],['right','→']].map(([id,label])=>'<button data-move="'+id+'" aria-label="'+label+' 이동">'+label+'</button>').join('')+'</div><div class="button-pair"><button class="secondary" data-action="cancel-layout">취소</button><button class="primary" data-action="save-layout" '+(bad?'disabled':'')+'>배치 완료</button></div>';
}
function startFacilityEdit(id,kind){switchTab('world');const f=F.Shelter.facility(state,id);facilityDraft={id,kind,x:f?.x??.23,y:f?.y??.65};editor=true;scene.editing=false;$('world').classList.add('editing-layout');$('editor').hidden=false;$('targets').hidden=true;renderFacilityEditor();syncEditorViewport();}
